#!/usr/bin/env node
// Packed consumers (M8, P0.1): example pages served from tarballs installed outside the workspace.
// Each consumer installs only the packages it needs; its import map is generated by walking the
// installed modules through each package's `exports` (default, production conditions); its
// stylesheets must be published files; its CSP hash is recomputed. Bundled consumers (fresh Vite
// TypeScript, React, Vue, Svelte, and Angular projects) also install their build tools,
// type-check, and are served from their build output (Vite's, or the Angular CLI's). The golden
// path (P0.5, scripts/golden-path.mjs) builds a library, its Workbench site, and an app on it.
// ODDKIN_CONSUMERS_FROM=<dist-tag or version> installs the published packages instead of
// tarballs. Run after `npm run build`.
//
//   node scripts/packed-consumers.mjs --port 4174
//   node scripts/packed-consumers.mjs --import-map examples/full-app   (prints the workspace map)
//
// Serves /<consumer>/ for each consumer below; packing starts on the first request for it, and
// /<consumer>/__ready reports the installed packages, the import map, and every module file the
// page loads (e2e/packed-consumers.spec.ts, e2e/components-only.spec.ts), and for the golden path
// the library's tarball and each step's time (e2e/golden-path.spec.ts).
import { execFile } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createServer } from 'node:http';
import { cp, mkdir, readdir, readFile, realpath, rm, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, extname, join, normalize, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';
import { init, parse } from 'es-module-lexer';

const root = resolve(fileURLToPath(new URL('..', import.meta.url)));

/** Each consumer: the packages it installs, the example page, and the files copied from it. */
export const CONSUMERS = {
  'css-only': {
    packages: ['tokens'],
    page: 'examples/tokens-css-only',
    files: ['index.html', 'styles.css', 'theme.json'],
    // The CSS-only path: the installed CLI generates the stylesheet the page links.
    generate: ['build', 'theme.json', '--out', 'generated', '--format', 'css', '--strict'],
  },
  // CSS only with the recipes: the theme stylesheet and components' CSS (layout.css among them),
  // no script. Core is installed only as the components package's dependency.
  'css-recipes': {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/css-recipes',
    files: ['index.html'],
  },
  'core-only': {
    packages: ['core'],
    page: 'examples/core-counter',
    files: ['index.html', 'styles.css', 'dist'],
  },
  'components-only': {
    packages: ['core', 'tokens', 'components'],
    page: 'examples/components-only',
    files: ['index.html', 'main.js', 'styles.css'],
  },
  'full-app': {
    packages: ['core', 'tokens', 'components', 'state', 'app', 'ai'],
    page: 'examples/full-app',
    files: ['index.html', 'main.js', 'styles.css'],
  },
  // The optional autoloader (ADR 0046 D9) beside the same markup with explicit define imports.
  autoload: {
    packages: ['core', 'tokens', 'components'],
    page: 'examples/autoload',
    files: ['index.html', 'explicit.html', 'autoload.js', 'explicit.js', 'styles.css'],
    pages: ['index.html', 'explicit.html'],
    // The autoloader imports define/* entries by URL, which no static graph shows.
    dynamicDefines: true,
  },
  // Bundled consumers: a fresh project installs the packed packages and its own build tools,
  // type-checks when it is TypeScript, and is served from its build output (`vite build` unless
  // `build` names another command; `dist` is the output directory).
  'vite-ts': {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/consumers/vite-ts',
    files: ['index.html', 'main.ts', 'styles.scss', 'tsconfig.json'],
    tools: ['vite', 'sass', 'typescript'],
    check: ['typescript/bin/tsc', '-p', '.'],
    bundle: true,
  },
  react: {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/consumers/react',
    files: ['index.html', 'main.tsx', 'tsconfig.json', 'vite.config.mjs'],
    tools: [
      'vite',
      '@vitejs/plugin-react',
      'react',
      'react-dom',
      '@types/react',
      '@types/react-dom',
      'typescript',
    ],
    check: ['typescript/bin/tsc', '-p', '.'],
    bundle: true,
  },
  vue: {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/consumers/vue',
    files: ['index.html', 'main.mjs', 'App.vue', 'vite.config.mjs'],
    tools: ['vite', '@vitejs/plugin-vue', 'vue'],
    bundle: true,
  },
  svelte: {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/consumers/svelte',
    files: ['index.html', 'main.mjs', 'App.svelte', 'vite.config.mjs'],
    tools: ['vite', '@sveltejs/vite-plugin-svelte', 'svelte'],
    bundle: true,
  },
  // The Angular CLI's application builder (AOT, strict templates) instead of Vite.
  angular: {
    packages: ['core', 'tokens', 'components'],
    page: 'tests/consumers/angular',
    files: ['angular.json', 'tsconfig.json', 'src'],
    tools: [
      '@angular/build',
      '@angular/cli',
      '@angular/compiler-cli',
      '@angular/common',
      '@angular/compiler',
      '@angular/core',
      '@angular/platform-browser',
      'rxjs',
      'tslib',
      // Angular 22.2 compiles with TypeScript 6.0, not the workspace's 7.
      'typescript@6.0.3',
    ],
    bundle: true,
    build: ['@angular/cli/bin/ng.js', 'build', '--base-href', './'],
    dist: 'dist/browser',
  },
  // The golden path: a library team's workspaces (the library and its Workbench site) and another
  // team's app on the library's tarball (scripts/golden-path.mjs). The app is served at
  // /golden-path/, the site at /golden-path/site/.
  'golden-path': { goldenPath: true },
};

// Build tools at the versions the workspace verifies; the rest pinned (checked 2026-10-28). A spec
// with its own version (`name@version`) is installed as written.
const PINNED = {
  sass: '1.107.0',
  '@vitejs/plugin-react': '6.1.2',
  '@vitejs/plugin-vue': '6.0.10',
  // The Angular CLI at the Angular version the workspace verifies (checked 2026-10-29).
  '@angular/build': '22.2.3',
  '@angular/cli': '22.2.3',
  '@angular/compiler-cli': '22.2.3',
};
async function toolSpec(name) {
  if (/^@?[^@]+@/.test(name)) return name;
  if (PINNED[name]) return `${name}@${PINNED[name]}`;
  const manifest = JSON.parse(
    await readFile(join(root, 'node_modules', ...name.split('/'), 'package.json'), 'utf8'),
  );
  return `${name}@${manifest.version}`;
}

async function filesUnder(dir, base = dir) {
  const out = [];
  for (const entry of await readdir(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    if (entry.isDirectory()) out.push(...(await filesUnder(path, base)));
    else out.push(`./${relative(base, path).split(sep).join('/')}`);
  }
  return out.sort();
}

const npmCli = process.env['npm_execpath']?.endsWith('.js')
  ? process.env['npm_execpath']
  : join(dirname(process.execPath), 'node_modules', 'npm', 'bin', 'npm-cli.js');
const execFileAsync = promisify(execFile);
// Asynchronous: a fresh project's install takes minutes, and the server keeps answering meanwhile.
const run = async (args, cwd) => {
  const running = execFileAsync(process.execPath, args, {
    cwd,
    encoding: 'utf8',
    maxBuffer: 64 * 1024 * 1024,
  });
  running.child.stdin?.end();
  return (await running).stdout;
};
const npm = (args, cwd) => run([npmCli, ...args], cwd);

const exported = (manifest, subpath, condition) => {
  const target = manifest.exports?.[subpath];
  return typeof target === 'string' ? target : (target?.[condition] ?? target?.default);
};

/** The file a bare specifier resolves to through the package's `exports` under `modules`. */
async function resolveSpecifier(modules, specifier, condition) {
  const match = /^(@[^/]+\/[^/]+)(?:\/(.+))?$/.exec(specifier);
  if (!match) throw new Error(`${specifier}: not a scoped package`);
  const dir = await realpath(join(modules, ...match[1].split('/')));
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const path = exported(manifest, match[2] ? `./${match[2]}` : '.', condition);
  if (!path) throw new Error(`${specifier}: not exported by ${match[1]}`);
  return join(dir, path);
}

const urlFrom = (from, file) => {
  const path = relative(from, file).split(sep).join('/');
  return path.startsWith('.') ? path : `./${path}`;
};

/** Every define/* entry of @oddkin/components under `modules`, as files. */
async function defineEntries(modules, condition) {
  const dir = await realpath(join(modules, '@oddkin', 'components'));
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  return Object.keys(manifest.exports ?? {})
    .filter((key) => key.startsWith('./define/'))
    .map((key) => join(dir, exported(manifest, key, condition)));
}

/** The module scripts an HTML page loads, as files. */
const moduleScripts = (html, dir) =>
  [...html.matchAll(/<script type="module" src="([^"]+)"/g)].map(([, src]) => resolve(dir, src));

/**
 * The import map for everything reachable from `entries` (bare specifiers resolved under
 * `modules` with `condition`), with URLs relative to `pageDir`, and every module file visited.
 */
export async function importMap(entries, { modules, pageDir, condition = 'default' }) {
  await init;
  const imports = {};
  const files = new Set();
  const visit = async (file) => {
    if (files.has(file)) return;
    files.add(file);
    const [records] = parse(await readFile(file, 'utf8'));
    for (const { specifier } of records) {
      if (!specifier) continue;
      if (specifier.startsWith('.')) {
        await visit(resolve(dirname(file), specifier));
        continue;
      }
      const target = await resolveSpecifier(modules, specifier, condition);
      imports[specifier] = urlFrom(pageDir, target);
      await visit(target);
    }
  };
  for (const entry of entries) await visit(entry);
  return {
    imports: Object.fromEntries(Object.entries(imports).sort(([a], [b]) => a.localeCompare(b))),
    files: [...files].map((file) => urlFrom(pageDir, file)).sort(),
  };
}

/** A workspace path such as ../../packages/tokens/dist/css/default.css as its published file. */
async function publishedFile(site, path) {
  const [, name, file] = /^\.\.\/\.\.\/packages\/([^/]+)\/(.+)$/.exec(path) ?? [];
  if (!name) return path;
  const dir = join(site, 'node_modules', '@oddkin', name);
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const published = Object.keys(manifest.exports ?? {}).some(
    (key) => exported(manifest, key, 'default') === `./${file}`,
  );
  if (!published) throw new Error(`${path}: not a published file of @oddkin/${name}`);
  return urlFrom(site, join(dir, file));
}

/** Rewrite a page's import map (and the CSP hash of that inline script) to `imports`. */
function withImportMap(html, imports) {
  if (!/<script type="importmap">/.test(html)) return html;
  const map = `\n${JSON.stringify({ imports }, null, 2)}\n`;
  const hash = createHash('sha256').update(map).digest('base64');
  return html
    .replace(/(<script type="importmap">)[\s\S]*?(<\/script>)/, `$1${map}$2`)
    .replace(/'sha256-[^']+'/, `'sha256-${hash}'`);
}

const tarballs = new Map();
// ODDKIN_CONSUMERS_FROM=<dist-tag or version> installs the published packages instead of
// tarballs (the registry smoke, .github/workflows/registry-smoke.yml).
const registry = process.env['ODDKIN_CONSUMERS_FROM'];
/** Pack each workspace package once per process (a failed pack is tried again next time). */
function pack(name, work) {
  if (!tarballs.has(name)) {
    const packing = npm(
      ['pack', '--json', '--pack-destination', work],
      join(root, 'packages', name),
    ).then((output) => join(work, JSON.parse(output)[0].filename));
    packing.catch(() => tarballs.delete(name));
    tarballs.set(name, packing);
  }
  return tarballs.get(name);
}

/** Install `specs` into the project `dir`. */
async function install(dir, specs) {
  const args = ['install', '--no-audit', '--no-fund', '--ignore-scripts', ...specs];
  if (registry) return void (await npm(args, dir));
  // Exact tool versions come from the npm cache when it has them; when its metadata is too old to
  // know a version a dependency asks for (ETARGET), npm asks the registry.
  try {
    await npm([...args, '--prefer-offline'], dir);
  } catch (error) {
    if (!/ETARGET/.test(String(error.stderr ?? error.message))) throw error;
    await npm(args, dir);
  }
}

/** A fresh project in `dir` (emptied first) with `specs` installed. */
async function freshProject(dir, specs) {
  await rm(dir, { recursive: true, force: true });
  await mkdir(dir, { recursive: true });
  await writeFile(
    join(dir, 'package.json'),
    JSON.stringify({ name: 'packed-consumer', private: true, type: 'module' }),
  );
  await install(dir, specs);
}

/** Every package installed in the project `dir`, sorted. */
async function installedIn(dir) {
  const installed = new Set();
  const walk = (deps = {}) => {
    for (const [dep, info] of Object.entries(deps)) {
      installed.add(dep);
      walk(info.dependencies);
    }
  };
  walk(JSON.parse(await npm(['ls', '--all', '--json'], dir)).dependencies);
  return [...installed].sort();
}

/**
 * Pack, install, and copy the consumer's page into `work/<name>` (emptied first). Returns the
 * site directory, the installed packages, the import map, and every module file the page loads.
 */
export async function packConsumer(name, work) {
  const consumer = CONSUMERS[name];
  if (!consumer) throw new Error(`Unknown consumer ${name}`);
  await mkdir(join(work, 'tarballs'), { recursive: true });
  const oddkin = (pkg) =>
    registry ? `@oddkin/${pkg}@${registry}` : pack(pkg, join(work, 'tarballs'));
  const site = join(work, name);
  if (consumer.goldenPath) {
    await rm(site, { recursive: true, force: true });
    await mkdir(site, { recursive: true });
    const { buildGoldenPath } = await import('./golden-path.mjs');
    const helpers = {
      root,
      oddkin,
      tool: toolSpec,
      tarballs: !registry,
      install,
      freshProject,
      installedIn,
      filesUnder,
      run,
      npm,
    };
    return buildGoldenPath(site, `/${name}/`, helpers);
  }
  await freshProject(site, [
    ...(await Promise.all(consumer.packages.map(oddkin))),
    ...(await Promise.all((consumer.tools ?? []).map(toolSpec))),
  ]);
  const installed = await installedIn(site);

  const pageDir = join(root, consumer.page);
  for (const file of consumer.files)
    await cp(join(pageDir, file), join(site, file), {
      recursive: true,
      filter: (source) => !/\.(map|tsbuildinfo)$|\.d\.ts$/.test(source),
    });
  if (consumer.generate) {
    const manifest = JSON.parse(
      await readFile(join(site, 'node_modules/@oddkin/tokens/package.json'), 'utf8'),
    );
    const bin = join(site, 'node_modules/@oddkin/tokens', Object.values(manifest.bin)[0]);
    await run([bin, ...consumer.generate], site);
  }
  if (consumer.bundle) {
    const [checker, ...args] = consumer.check ?? [];
    if (checker) await run([join(site, 'node_modules', checker), ...args], site);
    const vite = ['vite/bin/vite.js', 'build', '--base', './', '--outDir', 'dist', '--emptyOutDir'];
    const [builder, ...build] = consumer.build ?? vite;
    await run([join(site, 'node_modules', builder), ...build], site);
    const dist = join(site, consumer.dist ?? 'dist');
    return {
      site: dist,
      installed: installed.filter((dep) => dep.startsWith('@oddkin/')),
      imports: {},
      files: await filesUnder(dist),
    };
  }
  const modules = join(site, 'node_modules');
  const dynamic = consumer.dynamicDefines ? await defineEntries(modules, 'default') : [];
  let result;
  for (const page of consumer.pages ?? ['index.html']) {
    let html = await readFile(join(site, page), 'utf8');
    const map = await importMap([...moduleScripts(html, site), ...dynamic], {
      modules,
      pageDir: site,
    });
    html = withImportMap(html, map.imports);
    for (const [, href] of html.matchAll(/href="([^"]+)"/g))
      html = html.replace(`href="${href}"`, `href="${await publishedFile(site, href)}"`);
    if (html.includes('../../')) throw new Error(`${name}: ${page} still references the workspace`);
    await writeFile(join(site, page), html);
    result ??= map;
  }
  return { site, installed, ...result };
}

const types = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
};

function serve(port) {
  // One directory per port: a server stopped without cleanup (Windows) leaves at most one copy.
  const work = join(tmpdir(), `oddkin-packed-consumers-${port}`);
  const packed = new Map();
  const ready = (name) => {
    if (!packed.has(name)) packed.set(name, packConsumer(name, work));
    return packed.get(name);
  };
  const server = createServer(async (request, response) => {
    const url = new URL(request.url ?? '/', 'http://localhost');
    if (url.pathname === '/__health') return void response.writeHead(200).end('ok');
    const [, name, rest = ''] = /^\/([^/]+)(\/.*)?$/.exec(url.pathname) ?? [];
    if (!name || !CONSUMERS[name]) return void response.writeHead(404).end('Not found');
    if (!rest) return void response.writeHead(301, { location: `/${name}/` }).end();
    let consumer;
    try {
      consumer = await ready(name);
    } catch (error) {
      packed.delete(name);
      // A failed command's message holds its stderr; tsc reports on stdout.
      const report = [error.message ?? String(error), error.stdout].filter(Boolean).join('\n');
      return void response.writeHead(500).end(report);
    }
    if (rest === '/__ready') {
      // Everything but the local directory.
      const { site, ...report } = consumer;
      response.writeHead(200, { 'content-type': types['.json'] });
      return void response.end(JSON.stringify(report));
    }
    let path = normalize(join(consumer.site, decodeURIComponent(rest)));
    if (path !== consumer.site && !path.startsWith(consumer.site + sep))
      return void response.writeHead(403).end('Forbidden');
    try {
      if ((await stat(path)).isDirectory()) path = join(path, 'index.html');
      const body = await readFile(path);
      response.writeHead(200, {
        'content-type': types[extname(path)] ?? 'application/octet-stream',
      });
      response.end(body);
    } catch {
      response.writeHead(404).end('Not found');
    }
  });
  const stop = () => {
    server.close();
    rm(work, { recursive: true, force: true }).finally(() => process.exit(0));
  };
  process.on('SIGINT', stop);
  process.on('SIGTERM', stop);
  server.listen(port, '127.0.0.1', () =>
    console.log(
      `Packed consumers at http://127.0.0.1:${port}/<${Object.keys(CONSUMERS).join('|')}>/`,
    ),
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const arg = (flag) => {
    const i = process.argv.indexOf(flag);
    return i > -1 ? process.argv[i + 1] : undefined;
  };
  const page = arg('--import-map');
  if (page) {
    // The workspace import map of a page (development builds), for its index.html.
    const pageDir = resolve(root, page);
    const html = await readFile(join(pageDir, arg('--html') ?? 'index.html'), 'utf8');
    const consumer = Object.values(CONSUMERS).find(
      (c) => c.page && resolve(root, c.page) === pageDir,
    );
    const modules = join(root, 'node_modules');
    const dynamic = consumer?.dynamicDefines ? await defineEntries(modules, 'development') : [];
    const { imports } = await importMap([...moduleScripts(html, pageDir), ...dynamic], {
      modules,
      pageDir,
      condition: 'development',
    });
    console.log(JSON.stringify({ imports }, null, 2));
  } else serve(Number(arg('--port') ?? 4174));
}
